"""Topology abstractions for the network simulation stack."""

from collections import OrderedDict

from netsim.link import TCLink
from netsim.node import Host, OVSSwitch


class Topo:
    """Base topology builder."""

    def __init__(self):
        self._hosts = OrderedDict()
        self._switches = OrderedDict()
        self._links = []

    def addHost(self, name, cls=Host, **params):
        self._hosts[name] = {"cls": cls, **params}
        return name

    def addSwitch(self, name, cls=OVSSwitch, **params):
        self._switches[name] = {"cls": cls, **params}
        return name

    def addLink(self, node1, node2, cls=TCLink, **params):
        self._links.append((node1, node2, {"cls": cls, **params}))
        return (node1, node2)

    def hosts(self):
        return list(self._hosts)

    def switches(self):
        return list(self._switches)

    def links(self):
        return [(node1, node2) for node1, node2, _ in self._links]

    def nodeInfo(self, name):
        if name in self._hosts:
            return dict(self._hosts[name])
        if name in self._switches:
            return dict(self._switches[name])
        raise KeyError(name)

    def linkInfo(self, node1, node2):
        for left, right, info in self._links:
            if (left, right) == (node1, node2) or (left, right) == (node2, node1):
                return dict(info)
        raise KeyError((node1, node2))


class LinearTopo(Topo):
    """Linear chain of switches with one host per switch."""

    def __init__(self, k=2, **link_params):
        super().__init__()
        if k <= 0:
            return

        previous_switch = None
        for index in range(1, k + 1):
            switch = self.addSwitch(f"s{index}")
            host = self.addHost(f"h{index}")
            self.addLink(host, switch, **link_params)
            if previous_switch is not None:
                self.addLink(previous_switch, switch, **link_params)
            previous_switch = switch


class SingleSwitchTopo(Topo):
    """A single switch connected to k hosts."""

    def __init__(self, k=2, **link_params):
        super().__init__()
        switch = self.addSwitch("s1")
        for index in range(1, k + 1):
            host = self.addHost(f"h{index}")
            self.addLink(host, switch, **link_params)


class TreeTopo(Topo):
    """A tree of switches with hosts attached at the leaves."""

    def __init__(self, depth=1, fanout=2, **link_params):
        super().__init__()
        self._switch_index = 0
        self._host_index = 0
        if depth > 0 and fanout > 0:
            self._add_subtree(depth, fanout, parent_switch=None, link_params=link_params)

    def _next_switch(self):
        self._switch_index += 1
        return self.addSwitch(f"s{self._switch_index}")

    def _next_host(self):
        self._host_index += 1
        return self.addHost(f"h{self._host_index}")

    def _add_subtree(self, depth, fanout, parent_switch, link_params):
        switch = self._next_switch()
        if parent_switch is not None:
            self.addLink(parent_switch, switch, **link_params)

        if depth == 1:
            for _ in range(fanout):
                host = self._next_host()
                self.addLink(host, switch, **link_params)
            return switch

        for _ in range(fanout):
            self._add_subtree(depth - 1, fanout, switch, link_params)
        return switch

