class Node:
    """Base network node."""

    def __init__(self, name, **params):
        self.name = name
        self.params = dict(params)
        self.intfs = {}
        self.ip = self.params.get("ip")

    def addIntf(self, intf):
        """Attach an interface to the next available port."""
        self.intfs[intf.port] = intf

    def intfList(self):
        """Return interfaces ordered by port."""
        return [self.intfs[port] for port in sorted(self.intfs)]

    def defaultIntf(self):
        """Return the lowest-numbered interface if present."""
        if not self.intfs:
            return None
        return self.intfs[min(self.intfs)]

    @property
    def ports(self):
        """Return the allocated port numbers."""
        return sorted(self.intfs)

    def __repr__(self):
        return f"{self.__class__.__name__}({self.name!r})"


