"""Mobility models for Mininet-WiFi."""

import math

import numpy as np


class RandomWaypointMobility:
    """Deterministic random-waypoint mobility model."""

    def __init__(self, area_width, area_height, speed_range=(1.0, 5.0), seed=None):
        self.area_width = float(area_width)
        self.area_height = float(area_height)
        self.speed_range = tuple(speed_range)
        self.random = np.random.RandomState(seed)

    def _random_target(self):
        return (
            float(self.random.uniform(0.0, self.area_width)),
            float(self.random.uniform(0.0, self.area_height)),
        )

    def _random_speed(self):
        low, high = self.speed_range
        return float(self.random.uniform(low, high))

    def generate_trace(self, start_pos, num_steps):
        """Return a list of positions visited over the requested steps."""
        position = (float(start_pos[0]), float(start_pos[1]))
        target = self._random_target()
        speed = self._random_speed()
        trace = []

        for _ in range(int(num_steps)):
            dx = target[0] - position[0]
            dy = target[1] - position[1]
            distance = math.hypot(dx, dy)

            if distance <= speed:
                position = target
                target = self._random_target()
                speed = self._random_speed()
            elif distance > 0.0:
                position = (
                    position[0] + (dx / distance) * speed,
                    position[1] + (dy / distance) * speed,
                )

            trace.append(position)

        return trace

