"""Mininet-WiFi network engine."""

from netsim.net import Mininet
from netsim.utils import distance_2d
from netsim.wifi.accesspoint import AccessPoint
from netsim.wifi.propagation import received_signal_strength
from netsim.wifi.station import Station


class MininetWifi(Mininet):
    """Mininet extension with wireless stations and access points."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.stations = []
        self.access_points = []

    def addStation(self, name, cls=None, **params):
        station_cls = cls or Station
        station = super().addHost(name, cls=station_cls, **params)
        self.stations.append(station)
        return station

    def addAccessPoint(self, name, cls=None, **params):
        ap_cls = cls or AccessPoint
        ap = super().addSwitch(name, cls=ap_cls, **params)
        self.access_points.append(ap)
        return ap

    def auto_associate(self):
        """Associate each station with the strongest in-range AP."""
        for ap in self.access_points:
            ap.associated_stations = []

        for station in self.stations:
            best_ap = None
            best_rssi = None
            for ap in self.access_points:
                distance = distance_2d(station.position, ap.position)
                rssi = received_signal_strength(
                    tx_power_dbm=ap.tx_power_dbm,
                    freq_hz=ap.freq_hz,
                    distance_m=distance,
                    path_loss_exp=ap.path_loss_exp,
                )
                if rssi < ap.min_rssi_dbm:
                    continue
                if best_rssi is None or rssi > best_rssi:
                    best_ap = ap
                    best_rssi = rssi

            station.associated_ap = best_ap
            if best_ap is not None:
                best_ap.associated_stations.append(station)

        return {station.name: (station.associated_ap.name if station.associated_ap else None) for station in self.stations}

    def count_associated(self):
        return sum(station.associated_ap is not None for station in self.stations)

