"""Service function chain modeling."""

from dataclasses import dataclass
from functools import reduce
from operator import mul


@dataclass
class VNF:
    """Virtual network function."""

    name: str
    processing_delay_ms: float
    overhead_pct: float

    @property
    def throughput_factor(self):
        return 1.0 - (self.overhead_pct / 100.0)


class ServiceFunctionChain:
    """A linear service function chain with per-link parameters."""

    def __init__(self, vnfs, link_bw, link_delay):
        self.vnfs = list(vnfs)
        self.link_bw = float(link_bw)
        self.link_delay = float(link_delay)

    @property
    def num_links(self):
        return len(self.vnfs) + 1

    def compute_throughput(self):
        factors = [vnf.throughput_factor for vnf in self.vnfs]
        return self.link_bw * reduce(mul, factors, 1.0)

    def compute_latency(self):
        processing = sum(vnf.processing_delay_ms for vnf in self.vnfs)
        return (self.num_links * self.link_delay) + processing

