from netsim.container import DockerHost
from netsim.net import Mininet
from netsim.node import Host
from netsim.utils import jains_fairness_index


class Containernet(Mininet):
    """Mininet extension with Docker-backed hosts."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.docker_hosts = []

    def addDocker(self, name, image, cls=None, **params):
        docker_cls = cls or DockerHost
        docker = super().addHost(name, cls=docker_cls, image=image, **params)
        self.docker_hosts.append(docker)
        return docker

    def compute_resource_fairness(self):
        shares = [docker.cpu_shares for docker in self.docker_hosts]
        return jains_fairness_index(shares)

    def total_nodes(self):
        return len(self.hosts) + len(self.switches)

    def startup_overhead_ratio(self):
        if self.docker_hosts:
            docker_startup = self.docker_hosts[0].startup_time_ms
        else:
            docker_startup = DockerHost("docker-probe", image="probe").startup_time_ms
        return docker_startup / Host.STARTUP_TIME_MS

