"""P4-programmable switch simulation."""

from collections import OrderedDict

from netsim.node import Switch
from netsim.topo import Topo


class P4MatchActionTable:
    """A P4 match-action table."""

    def __init__(self, name, match_fields, max_size=1024):
        self.name = name
        self.match_fields = list(match_fields)
        self.max_size = int(max_size)
        self._rules = []
        self._insert_order = 0

    def add_rule(self, match_dict, action_name, action_params=None, priority=0):
        if len(self._rules) >= self.max_size:
            raise ValueError(f"table {self.name} is full")
        rule = {
            "match_dict": dict(match_dict),
            "action_name": action_name,
            "action_params": dict(action_params or {}),
            "priority": int(priority),
            "order": self._insert_order,
        }
        self._insert_order += 1
        self._rules.append(rule)
        return rule

    def lookup(self, packet_headers):
        matches = []
        for rule in self._rules:
            if all(packet_headers.get(field) == value for field, value in rule["match_dict"].items()):
                matches.append(rule)
        if not matches:
            return None
        matches.sort(
            key=lambda rule: (
                rule["priority"],
                len(rule["match_dict"]),
                -rule["order"],
            ),
            reverse=True,
        )
        return matches[0]

    def delete_rule(self, match_dict):
        target = dict(match_dict)
        for index, rule in enumerate(self._rules):
            if rule["match_dict"] == target:
                del self._rules[index]
                return True
        return False

    def size(self):
        return len(self._rules)

    def clear(self):
        self._rules.clear()


class P4Parser:
    """Extract fixed-position header fields from packet bytes."""

    def __init__(self, header_defs):
        self.header_defs = dict(header_defs)

    @property
    def header_size(self):
        if not self.header_defs:
            return 0
        return max(offset + length for offset, length in self.header_defs.values())

    def is_valid(self, packet_data):
        return len(packet_data) >= self.header_size

    def parse(self, packet_data):
        if not self.is_valid(packet_data):
            raise ValueError("packet is too short for the parser definition")
        headers = {}
        for field_name, (offset, length) in self.header_defs.items():
            field_bytes = packet_data[offset : offset + length]
            headers[field_name] = int.from_bytes(field_bytes, byteorder="big")
        return headers


class P4Deparser:
    """Rebuild packet bytes from parsed headers and payload."""

    def __init__(self, header_defs):
        self.header_defs = dict(header_defs)

    @property
    def header_size(self):
        if not self.header_defs:
            return 0
        return max(offset + length for offset, length in self.header_defs.values())

    def deparse(self, headers, payload):
        buffer = bytearray(self.header_size)
        for field_name, (offset, length) in sorted(self.header_defs.items(), key=lambda item: item[1][0]):
            value = headers.get(field_name, 0)
            if isinstance(value, (bytes, bytearray)):
                field_bytes = bytes(value[:length]).rjust(length, b"\x00")
            else:
                field_bytes = int(value).to_bytes(length, byteorder="big", signed=False)
            buffer[offset : offset + length] = field_bytes
        return bytes(buffer) + bytes(payload)


class P4Counter:
    """Per-index packet and byte counter."""

    def __init__(self, name, size):
        self.name = name
        self.size_limit = int(size)
        self.packet_counts = [0] * self.size_limit
        self.byte_counts = [0] * self.size_limit

    def _validate_index(self, index):
        if index < 0 or index >= self.size_limit:
            raise IndexError(index)

    def increment(self, index, packet_bytes):
        self._validate_index(index)
        packet_len = len(packet_bytes) if isinstance(packet_bytes, (bytes, bytearray)) else int(packet_bytes)
        self.packet_counts[index] += 1
        self.byte_counts[index] += packet_len

    def read(self, index):
        self._validate_index(index)
        return self.packet_counts[index], self.byte_counts[index]

    def reset(self, index=None):
        if index is None:
            self.packet_counts = [0] * self.size_limit
            self.byte_counts = [0] * self.size_limit
            return
        self._validate_index(index)
        self.packet_counts[index] = 0
        self.byte_counts[index] = 0

    def total_packets(self):
        return sum(self.packet_counts)

    def total_bytes(self):
        return sum(self.byte_counts)


class P4Switch(Switch):
    """Switch with a programmable parser and match-action pipeline."""

    def __init__(self, name, program=None, **params):
        super().__init__(name, **params)
        self.program = program
        self.tables = OrderedDict()
        self.counters = OrderedDict()
        self.parser = None
        self.deparser = None
        self.multicast_groups = {}

    def add_table(self, table):
        self.tables[table.name] = table
        return table

    def add_counter(self, counter):
        self.counters[counter.name] = counter
        return counter

    def set_parser(self, parser):
        self.parser = parser
        return parser

    def set_deparser(self, deparser):
        self.deparser = deparser
        return deparser

    def add_multicast_group(self, group):
        self.multicast_groups[group.group_id] = group
        return group

    def get_table(self, name):
        return self.tables.get(name)

    def get_counter(self, name):
        return self.counters.get(name)

    @property
    def pipeline_latency_us(self):
        return 0.5 * len(self.tables)

    def _increment_counter(self, counter_name, counter_index, packet_data):
        if counter_name is None:
            return
        counter = self.get_counter(counter_name)
        if counter is None:
            raise KeyError(counter_name)
        counter.increment(int(counter_index), packet_data)

    def _apply_action(self, action_name, action_params, headers, payload, packet_data):
        counter_name = action_params.get("counter")
        counter_index = action_params.get("index", action_params.get("counter_index", 0))
        if counter_name is not None:
            self._increment_counter(counter_name, counter_index, packet_data)

        if action_name in (None, "noop", "forward", "output"):
            return headers, payload
        if action_name == "drop":
            return None
        if action_name in ("set_field", "modify_field"):
            if "field" in action_params and "value" in action_params:
                headers[action_params["field"]] = action_params["value"]
            else:
                for key, value in action_params.items():
                    if key not in {"counter", "index", "counter_index"}:
                        headers[key] = value
            return headers, payload
        if action_name == "set_fields":
            fields = action_params.get("fields", action_params)
            for key, value in fields.items():
                if key not in {"counter", "index", "counter_index"}:
                    headers[key] = value
            return headers, payload
        if action_name == "count":
            return headers, payload
        if action_name == "truncate":
            length = int(action_params.get("length", len(payload)))
            return headers, payload[:length]
        if action_name == "append_payload":
            return headers, payload + bytes(action_params.get("data", b""))
        if action_name == "multicast":
            group_id = action_params["group_id"]
            group = self.multicast_groups[group_id]
            if self.deparser is not None:
                packet_out = self.deparser.deparse(headers, payload)
            elif self.parser is not None:
                packet_out = P4Deparser(self.parser.header_defs).deparse(headers, payload)
            else:
                packet_out = bytes(packet_data)
            return group.replicate(packet_out)
        return headers, payload

    def process_packet(self, packet_data):
        packet_bytes = bytes(packet_data)
        if self.parser is not None:
            headers = self.parser.parse(packet_bytes)
            payload = packet_bytes[self.parser.header_size :]
        else:
            headers = {}
            payload = packet_bytes

        for table in self.tables.values():
            rule = table.lookup(headers)
            if rule is None:
                continue
            result = self._apply_action(
                rule["action_name"],
                rule["action_params"],
                headers,
                payload,
                packet_bytes,
            )
            if result is None:
                return None
            if isinstance(result, list):
                return result
            headers, payload = result

        if self.deparser is not None:
            return self.deparser.deparse(headers, payload)
        if self.parser is not None:
            return P4Deparser(self.parser.header_defs).deparse(headers, payload)
        return packet_bytes


class P4Topology(Topo):
    """Linear topology built from P4-capable switches."""

    def __init__(self, num_switches, num_hosts_per_switch, **link_params):
        super().__init__()
        self._host_index = 0
        previous_switch = None

        for switch_index in range(1, int(num_switches) + 1):
            switch = self.addP4Switch(f"s{switch_index}")
            for _ in range(int(num_hosts_per_switch)):
                self._host_index += 1
                host = self.addHost(f"h{self._host_index}")
                self.addLink(host, switch, **link_params)
            if previous_switch is not None:
                self.addLink(previous_switch, switch, **link_params)
            previous_switch = switch

    def addP4Switch(self, name, **params):
        return self.addSwitch(name, cls=P4Switch, **params)


class P4MulticastGroup:
    """A multicast group with a fixed set of output ports."""

    def __init__(self, group_id, ports):
        self.group_id = group_id
        self.ports = list(dict.fromkeys(ports))

    def replicate(self, packet_data):
        return [(port, packet_data) for port in self.ports]

    def add_port(self, port):
        if port not in self.ports:
            self.ports.append(port)

    def remove_port(self, port):
        if port in self.ports:
            self.ports.remove(port)

