"""SDN controller and flow-rule simulation."""

import heapq

from netsim.node import Switch


class FlowRule:
    """An OpenFlow-style flow rule."""

    def __init__(self, match_fields, actions, priority=100, idle_timeout=0, hard_timeout=0):
        self.match_fields = dict(match_fields)
        self.actions = list(actions)
        self.priority = int(priority)
        self.idle_timeout = float(idle_timeout)
        self.hard_timeout = float(hard_timeout)
        self.packet_count = 0
        self.byte_count = 0
        self.install_time = 0.0
        self.install_order = 0

    def is_expired(self, current_time, last_matched_time):
        reference_time = self.install_time if last_matched_time is None else last_matched_time
        if self.hard_timeout > 0 and (current_time - self.install_time) >= self.hard_timeout:
            return True
        if self.idle_timeout > 0 and (current_time - reference_time) >= self.idle_timeout:
            return True
        return False

    def matches(self, packet_headers):
        return all(packet_headers.get(field) == value for field, value in self.match_fields.items())


class FlowTable:
    """A per-switch flow table."""

    def __init__(self, switch_name, capacity=4096):
        self.switch_name = switch_name
        self.capacity = int(capacity)
        self.rules = []
        self._install_counter = 0
        self._last_matched_times = {}

    def install(self, rule):
        if self.size() >= self.capacity:
            raise ValueError(f"flow table for {self.switch_name} is at capacity")
        rule.install_order = self._install_counter
        self._install_counter += 1
        self.rules.append(rule)
        return rule

    def remove(self, match_fields):
        target = dict(match_fields)
        removed = 0
        remaining = []
        for rule in self.rules:
            if rule.match_fields == target:
                self._last_matched_times.pop(id(rule), None)
                removed += 1
            else:
                remaining.append(rule)
        self.rules = remaining
        return removed

    def lookup(self, packet_headers):
        matches = [rule for rule in self.rules if rule.matches(packet_headers)]
        if not matches:
            return None

        matches.sort(key=lambda rule: (rule.priority, -rule.install_order), reverse=True)
        rule = matches[0]
        packet_size = packet_headers.get(
            "size_bytes",
            packet_headers.get("packet_size", packet_headers.get("length", 0)),
        )
        current_time = packet_headers.get("timestamp", packet_headers.get("current_time", 0.0))
        rule.packet_count += 1
        rule.byte_count += int(packet_size)
        self._last_matched_times[id(rule)] = float(current_time)
        return rule

    def evict_expired(self, current_time, last_matched_times):
        evicted = 0
        remaining = []
        for rule in self.rules:
            last_matched_time = None
            if last_matched_times is not None:
                last_matched_time = last_matched_times.get(rule)
                if last_matched_time is None:
                    last_matched_time = last_matched_times.get(id(rule))
            if last_matched_time is None:
                last_matched_time = self._last_matched_times.get(id(rule))
            if rule.is_expired(float(current_time), last_matched_time):
                self._last_matched_times.pop(id(rule), None)
                evicted += 1
            else:
                remaining.append(rule)
        self.rules = remaining
        return evicted

    def size(self):
        return len(self.rules)

    def stats(self):
        return [(rule, rule.packet_count, rule.byte_count) for rule in self.rules]

    def clear(self):
        self.rules.clear()
        self._last_matched_times.clear()

    def utilization(self):
        if self.capacity <= 0:
            return 0.0
        return self.size() / self.capacity


class SDNController:
    """Base SDN controller with topology and flow-table management."""

    def __init__(self, name):
        self.name = name
        self.topology = {}
        self.flow_tables = {}
        self.hosts = set()
        self.host_ip_map = {}
        self.ip_to_host = {}
        self.port_map = {}
        self.installed_paths = {}
        self.net = None
        self._install_events = 0

    def _add_node(self, name):
        self.topology.setdefault(name, {})

    def add_switch(self, switch_name):
        self._add_node(switch_name)
        self.flow_tables.setdefault(switch_name, FlowTable(switch_name))
        self.port_map.setdefault(switch_name, {})

    def add_link(self, node1, node2, weight=1):
        self._add_node(node1)
        self._add_node(node2)
        edge_weight = float(weight)
        self.topology[node1][node2] = edge_weight
        self.topology[node2][node1] = edge_weight

    def remove_link(self, node1, node2):
        self.topology.get(node1, {}).pop(node2, None)
        self.topology.get(node2, {}).pop(node1, None)
        self.port_map.get(node1, {}).pop(node2, None)
        self.port_map.get(node2, {}).pop(node1, None)

    def topology_discovery(self, net):
        self.net = net
        self.topology = {}
        self.flow_tables = {}
        self.hosts = set()
        self.host_ip_map = {}
        self.ip_to_host = {}
        self.port_map = {}
        self.installed_paths = {}
        self._install_events = 0

        for switch in net.switches:
            self.add_switch(switch.name)

        for host in net.hosts:
            self._add_node(host.name)
            self.hosts.add(host.name)
            if host.ip:
                self.host_ip_map[host.name] = host.ip
                self.ip_to_host[host.ip] = host.name

        for link in net.links:
            node1 = link.node1.name
            node2 = link.node2.name
            weight = link.delay if link.delay > 0 else 1.0
            self.add_link(node1, node2, weight=weight)
            if node1 in self.flow_tables:
                self.port_map[node1][node2] = link.intf1.port
            if node2 in self.flow_tables:
                self.port_map[node2][node1] = link.intf2.port

        return self

    def compute_path(self, src, dst):
        if src == dst:
            return [src] if src in self.topology else []
        if src not in self.topology or dst not in self.topology:
            return []

        distances = {src: 0.0}
        previous = {src: None}
        queue = [(0.0, src)]
        visited = set()

        while queue:
            distance, node = heapq.heappop(queue)
            if node in visited:
                continue
            visited.add(node)
            if node == dst:
                break
            for neighbor in sorted(self.topology[node]):
                weight = self.topology[node][neighbor]
                candidate = distance + weight
                if candidate < distances.get(neighbor, float("inf")):
                    distances[neighbor] = candidate
                    previous[neighbor] = node
                    heapq.heappush(queue, (candidate, neighbor))

        if dst not in previous:
            return []

        path = []
        current = dst
        while current is not None:
            path.append(current)
            current = previous[current]
        return list(reversed(path))

    def compute_all_paths(self):
        paths = {}
        for src in sorted(self.hosts):
            for dst in sorted(self.hosts):
                if src == dst:
                    continue
                paths[(src, dst)] = self.compute_path(src, dst)
        return paths

    def _remove_rules_for_flow(self, src_ip, dst_ip):
        match_fields = {"src_ip": src_ip, "dst_ip": dst_ip}
        for flow_table in self.flow_tables.values():
            flow_table.remove(match_fields)

    def install_path_rules(self, path, src_ip, dst_ip, priority=100):
        if not path:
            return 0

        installed = 0
        match_fields = {"src_ip": src_ip, "dst_ip": dst_ip}
        self._remove_rules_for_flow(src_ip, dst_ip)

        for index, node_name in enumerate(path):
            if node_name not in self.flow_tables:
                continue
            if index + 1 >= len(path):
                continue
            next_hop = path[index + 1]
            out_port = self.port_map.get(node_name, {}).get(next_hop)
            if out_port is None:
                continue
            actions = [{"type": "output", "port": out_port}]
            rule = FlowRule(match_fields, actions, priority=priority)
            self.flow_tables[node_name].install(rule)
            installed += 1
            self._install_events += 1

        src_host = self.ip_to_host.get(src_ip)
        dst_host = self.ip_to_host.get(dst_ip)
        self.installed_paths[(src_ip, dst_ip)] = {
            "src_host": src_host,
            "dst_host": dst_host,
            "path": list(path),
        }
        return installed

    def total_rules_installed(self):
        return sum(flow_table.size() for flow_table in self.flow_tables.values())

    def handle_link_failure(self, node1, node2):
        self.remove_link(node1, node2)
        affected = []
        for flow_key, metadata in list(self.installed_paths.items()):
            path = metadata["path"]
            edges = list(zip(path, path[1:]))
            if (node1, node2) in edges or (node2, node1) in edges:
                affected.append((flow_key, metadata))

        reinstalled = 0
        for (src_ip, dst_ip), metadata in affected:
            self._remove_rules_for_flow(src_ip, dst_ip)
            src_host = metadata["src_host"]
            dst_host = metadata["dst_host"]
            new_path = self.compute_path(src_host, dst_host) if src_host and dst_host else []
            if new_path:
                reinstalled += self.install_path_rules(new_path, src_ip, dst_ip)
            else:
                self.installed_paths.pop((src_ip, dst_ip), None)
        return reinstalled


class ReactiveController(SDNController):
    """Installs rules on demand after table misses."""

    def __init__(self, name):
        super().__init__(name)
        self.packet_in_count = 0

    def handle_packet_in(self, switch_name, packet_headers):
        flow_table = self.flow_tables[switch_name]
        existing_rule = flow_table.lookup(packet_headers)
        if existing_rule is not None:
            return existing_rule

        self.packet_in_count += 1
        src_ip = packet_headers["src_ip"]
        dst_ip = packet_headers["dst_ip"]
        src_host = self.ip_to_host.get(src_ip)
        dst_host = self.ip_to_host.get(dst_ip)
        if src_host is None or dst_host is None:
            return []

        path = self.compute_path(src_host, dst_host)
        if not path:
            return []

        self.install_path_rules(path, src_ip, dst_ip, priority=packet_headers.get("priority", 100))
        return path


class ProactiveController(SDNController):
    """Pre-installs rules for every source and destination pair."""

    rule_install_time_ms = 0.1

    def install_all_rules(self, hosts_with_ips):
        hosts = []
        for entry in hosts_with_ips:
            if hasattr(entry, "name") and hasattr(entry, "ip"):
                hosts.append((entry.name, entry.ip))
            else:
                hosts.append((entry[0], entry[1]))

        installed = 0
        for src_name, src_ip in hosts:
            for dst_name, dst_ip in hosts:
                if src_name == dst_name:
                    continue
                path = self.compute_path(src_name, dst_name)
                if not path:
                    continue
                installed += self.install_path_rules(path, src_ip, dst_ip)
        return installed

    def total_install_time(self):
        return self._install_events * self.rule_install_time_ms
